{"source_evidence": {"v1.0.1:ParseBytes": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "bytes.go", "source_sha256": "9fb2391c3896a42cd4091279701f6274c19f3c3f15145503477229a67835d5da", "first_line": 110, "last_line": 143, "quote": "func ParseBytes(s string) (uint64, error) {
	lastDigit := 0
	hasComma := false
	for _, r := range s {
		if !(unicode.IsDigit(r) || r == '.' || r == ',') {
			break
		}
		if r == ',' {
			hasComma = true
		}
		lastDigit++
	}

	num := s[:lastDigit]
	if hasComma {
		num = strings.Replace(num, ",", "", -1)
	}

	f, err := strconv.ParseFloat(num, 64)
	if err != nil {
		return 0, err
	}

	extra := strings.ToLower(strings.TrimSpace(s[lastDigit:]))
	if m, ok := bytesSizeTable[extra]; ok {
		f *= float64(m)
		if f >= math.MaxUint64 {
			return 0, fmt.Errorf("too large: %v", s)
		}
		return uint64(f), nil
	}

	return 0, fmt.Errorf("unhandled size name: %v", extra)
}"}, "v1.0.1:ParseBigBytes": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "bigbytes.go", "source_sha256": "9318dd523505253f686747635394232cabe2968984df14b2f49d91926ea80c70", "first_line": 155, "last_line": 189, "quote": "func ParseBigBytes(s string) (*big.Int, error) {
	lastDigit := 0
	hasComma := false
	for _, r := range s {
		if !(unicode.IsDigit(r) || r == '.' || r == ',') {
			break
		}
		if r == ',' {
			hasComma = true
		}
		lastDigit++
	}

	num := s[:lastDigit]
	if hasComma {
		num = strings.Replace(num, ",", "", -1)
	}

	val := &big.Rat{}
	_, err := fmt.Sscanf(num, "%f", val)
	if err != nil {
		return nil, err
	}

	extra := strings.ToLower(strings.TrimSpace(s[lastDigit:]))
	if m, ok := bigBytesSizeTable[extra]; ok {
		mv := (&big.Rat{}).SetInt(m)
		val.Mul(val, mv)
		rv := &big.Int{}
		rv.Div(val.Num(), val.Denom())
		return rv, nil
	}

	return nil, fmt.Errorf("unhandled size name: %v", extra)
}"}, "v1.0.1:BigBytes": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "bigbytes.go", "source_sha256": "9318dd523505253f686747635394232cabe2968984df14b2f49d91926ea80c70", "first_line": 133, "last_line": 136, "quote": "func BigBytes(s *big.Int) string {
