}"}, "v1.0.1:BigIBytes": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "bigbytes.go", "source_sha256": "9318dd523505253f686747635394232cabe2968984df14b2f49d91926ea80c70", "first_line": 143, "last_line": 146, "quote": "func BigIBytes(s *big.Int) string {
