	return humanateBigBytes(s, bigIECExp, sizes)
}"}, "v1.0.1:humanateBigBytes": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "bigbytes.go", "source_sha256": "9318dd523505253f686747635394232cabe2968984df14b2f49d91926ea80c70", "first_line": 112, "last_line": 126, "quote": "func humanateBigBytes(s, base *big.Int, sizes []string) string {
	if s.Cmp(ten) < 0 {
		return fmt.Sprintf("%d B", s)
	}
	c := (&big.Int{}).Set(s)
	val, mag := oomm(c, base, len(sizes)-1)
	suffix := sizes[mag]
	f := "%.0f %s"
	if val < 10 {
		f = "%.1f %s"
	}

	return fmt.Sprintf(f, val, suffix)

}"}, "v1.0.1:oomm": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "big.go", "source_sha256": "26c2e7a009a1579f126853cbfb6c9ffc7cda00b4f5ca3faea4705c384cff5edf", "first_line": 8, "last_line": 19, "quote": "func oomm(n, b *big.Int, maxmag int) (float64, int) {
	mag := 0
	m := &big.Int{}
	for n.Cmp(b) >= 0 {
		n.DivMod(n, b, m)
		mag++
		if mag == maxmag && maxmag >= 0 {
			break
		}
	}
	return float64(n.Int64()) + (float64(m.Int64()) / float64(b.Int64())), mag
}"}, "v1.0.1:BigComma": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "comma.go", "source_sha256": "067d9654d89f6d55df0e10cdb907a1c5eaca786ae7d4225126ce6e68836bf3bf", "first_line": 89, "last_line": 116, "quote": "func BigComma(b *big.Int) string {
	sign := ""
	if b.Sign() < 0 {
		sign = "-"
		b.Abs(b)
	}

	athousand := big.NewInt(1000)
	c := (&big.Int{}).Set(b)
	_, m := oom(c, athousand)
	parts := make([]string, m+1)
	j := len(parts) - 1

	mod := &big.Int{}
	for b.Cmp(athousand) >= 0 {
		b.DivMod(b, athousand, mod)
		parts[j] = strconv.FormatInt(mod.Int64(), 10)
		switch len(parts[j]) {
		case 2:
			parts[j] = "0" + parts[j]
		case 1:
			parts[j] = "00" + parts[j]
		}
		j--
	}
	parts[j] = strconv.Itoa(int(b.Int64()))
	return sign + strings.Join(parts[j:], ",")
}"}, "v1.0.1:ParseSI": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "si.go", "source_sha256": "7159cff48cad974637868726cf45ff255b4a9c522a7b2eafcad3dfd537ba058e", "first_line": 117, "last_line": 127, "quote": "func ParseSI(input string) (float64, string, error) {
	found := riParseRegex.FindStringSubmatch(input)
	if len(found) != 4 {
		return 0, "", errInvalid
	}
	mag := revSIPrefixTable[found[2]]
	unit := found[3]

	base, err := strconv.ParseFloat(found[1], 64)
	return base * mag, unit, err
}"}, "v1.0.1:ComputeSI": {"revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "source_path": "si.go", "source_sha256": "7159cff48cad974637868726cf45ff255b4a9c522a7b2eafcad3dfd537ba058e", "first_line": 64, "last_line": 85, "quote": "func ComputeSI(input float64) (float64, string) {
	if input == 0 {
		return 0, ""
	}
	mag := math.Abs(input)
	exponent := math.Floor(logn(mag, 10))
	exponent = math.Floor(exponent/3) * 3

	value := mag / math.Pow(10, exponent)

	// Handle special case where value is exactly 1000.0
	// Should return 1 M instead of 1000 k
	if value == 1000.0 {
		exponent += 3
		value = mag / math.Pow(10, exponent)
	}

	value = math.Copysign(value, input)

	prefix := siPrefixTable[exponent]
	return value, prefix
}"}}, "owned_observations": [{"tag": "v1.0.0", "revision": "9f541cc9db5d55bce703bd99987c9d5cb8eea45e", "rows": [{"id": "parse-float-precision", "operation": "ParseBytes", "input": "9007199254740993", "observed": {"error_class": "none", "value": "9007199254740992"}, "pass": true}, {"id": "parse-new-big-unit", "operation": "ParseBytes", "input": "1 Rb", "observed": {"error_class": "unit", "value": "0"}, "pass": true}, {"id": "parse-uint64-max", "operation": "ParseBytes", "input": "18446744073709551615", "observed": {"error_class": "too-large", "value": "0"}, "pass": true}, {"id": "bigparse-exact-large", "operation": "ParseBigBytes", "input": "9007199254740993", "observed": {"error_class": "none", "value": "9007199254740993"}, "pass": true}, {"id": "bigparse-quettabyte", "operation": "ParseBigBytes", "input": "1 QB", "observed": {"error_class": "unit", "value": ""}, "pass": true}, {"id": "bigparse-quebibyte", "operation": "ParseBigBytes", "input": "1 QiB", "observed": {"error_class": "unit", "value": ""}, "pass": true}, {"id": "bigformat-quettabyte", "operation": "BigBytes", "input": "1000000000000000000000000000000", "observed": {"input_after": "1000000000000000000000000000000", "text": "1000000 YB"}, "pass": true}, {"id": "bigcomma-positive", "operation": "BigComma", "input": "1234567", "observed": {"input_after": "1", "text": "1,234,567"}, "pass": true}, {"id": "bigcomma-negative", "operation": "BigComma", "input": "-1234567", "observed": {"input_after": "1", "text": "-1,234,567"}, "pass": true}, {"id": "si-quecto", "operation": "ComputeSI", "input": "1e-30", "observed": {"prefix": "", "value": "1.0000000000000002"}, "pass": false}, {"id": "parse-si-quetta", "operation": "ParseSI", "input": "1 QB", "observed": {"error_class": "none", "unit": "QB", "value": "1"}, "pass": true}]}, {"tag": "v1.0.1", "revision": "9ec74ab2f7a7161664182fd4e5e292fccffbc75f", "rows": [{"id": "parse-float-precision", "operation": "ParseBytes", "input": "9007199254740993", "observed": {"error